	case a.Write != "":
		a.Write = id
	case a.Read != "":
		a.Read = id
	case a.Crash != "":
		a.Crash = id
	case a.Restart != "":
		a.Restart = id
	case a.Pause != "":
		a.Pause = id
	case a.Resume != "":
