"""Steward's decision-replay check (observe/schema.md v5 addendum, draft 5).
derives: C1.1, C3.1, C3.5, C3.7, C3.8, F3.2, F3.3 (decision inputs; evidence for each decision from its inputs;
C1.1 without a global order; decisions a function of their recorded inputs across runs)

usage: decision_replay.py [--extra-inputs a,b] <trace.jsonl>...   (every trace of one side: all schedules, seeds and
repetitions; --extra-inputs names the input names the artifact's README declares)

Part 1, evidence, per trace.
  storage    accept/serve iff token >= ledger; a served read returns stored_value; the record matches its inputs.
  Grant      its counted Agreed records name distinct nodes whose agreements are eligible for its configuration and
             form a majority of `members` (denominator the whole membership), and `members` is the committed
             configuration of its epoch, not only what the decider wrote (C3.7).
  ConfigCommitted (decided) of epoch e+1: counted by eligible majorities of e and of its members (C3.8); its
             members are its request's set; `readmits` is exactly the [node, inc > 0] in its members with an Agreed
             among its inputs. C3.1: one decided commit per epoch, and the committed configuration of its
             predecessor exists in the trace (not its order: see the stated limits).
  Eligibility: incarnation 0, or re-admitted by a decided commit of an epoch at most the configuration's, other than
             the commit being checked (contract/v3.md, "Eligible agreement").
  Input names outside the schema's fixed list (and --extra-inputs) are reported.
Part 2, C1.1 without a global order, per trace: no token granted twice; a grant under a higher config_epoch carries a
higher token than every grant under a lower one; each node's Agree records for counted grant proposals, in its own
(inc, seq) order, carry strictly increasing tokens; two grants with one grantor_term come from one (proc, inc).
Part 3, function of inputs (C3.5), across all traces: decisions of one kind with equal inputs (each ref replaced by
the content of the record it names, recursively; member lists as sets) must have equal outcomes.

Stated limits. An Agree is matched to the Agreed that counted it by (node, incarnation, proposal), not by causes.
C3.1's "e+1 only after e" is checked as existence, not order: file order on an implementation side is collection
order, which says nothing about when a commit happened (Fable's prereg review, finding 3); an e+1 commit counted by a
majority of e's committed members can only be evidenced after e exists, which part 1 checks. Everything else that
needs an order uses one process's own (inc, seq).
Exit status 1 if anything is reported.
"""
import json, sys
from collections import defaultdict

STORAGE = {'WriteAccept', 'WriteReject', 'ReadAccept', 'ReadReject'}
IDENT = {'proc', 'inc', 'seq', 'causes', 'run', 'side'}
FIXED = {'token', 'ledger', 'stored_value', 'value', 'agreed', 'members', 'config_epoch', 'grantor_term', 'last_token',
         'clock', 'last_grant_at', 'old_members', 'old_epoch', 'request_id', 'requested_members', 'pending', 'commit'}
SETS = {'members', 'old_members', 'requested_members', 'readmits'}


def key(r):
    return (r['proc'], r.get('inc', 0), r['seq'])


def rkey(ref):
    return (ref['proc'], ref.get('inc', 0), ref['seq'])


def load(path):
    return [json.loads(l) for l in open(path) if l.strip()]


def inmap(r):
    return {i['name']: i.get('value') for i in r.get('inputs', [])}


def is_decision(r):
    return r['event'] in STORAGE or r['event'] in ('Grant', 'ReconfigRefused') or \
        (r['event'] == 'ConfigCommitted' and r.get('decided') is True)


def norm(v, field=None):
    if isinstance(v, dict):
        return {k: norm(x, k) for k, x in sorted(v.items())}
    if isinstance(v, list) and field in SETS:
        return sorted(json.dumps(x, sort_keys=True) for x in v)
    if isinstance(v, list):
        return [norm(x) for x in v]
    return v


def canon(r, recs, depth=0):
    """The decision's inputs as a canonical string, each ref replaced by the referenced record's content."""
    items = []
    for i in r.get('inputs', []):
        item = {'name': i['name'], 'value': norm(i.get('value'), i['name'])}
        if 'ref' in i and depth < 6:
            t = recs.get(rkey(i['ref']))
            item['ref'] = None if t is None else \
                {k: norm(v, k) for k, v in sorted(t.items()) if k not in IDENT and k != 'inputs'} | \
                ({'inputs': canon(t, recs, depth + 1)} if 'inputs' in t else {})
        items.append(json.dumps(item, sort_keys=True))
    return json.dumps(sorted(items))


def outcome(r):
    e = r['event']
    if e in STORAGE:
        return ('storage', (e, json.dumps(r.get('value')) if e == 'ReadAccept' else None))
    if e == 'Grant':
        return ('Grant', (r.get('token'), r.get('client'), r.get('config_epoch')))
    if e == 'ConfigCommitted':
        return ('ConfigCommitted', (r.get('epoch'), tuple(sorted(r.get('members', []))),
                                    tuple(sorted(tuple(x) for x in r.get('readmits', [])))))
    return ('ReconfigRefused', (r.get('reason'),))


def prop_key(p):
    return json.dumps(norm(p), sort_keys=True)


def evidence(path, recs, allowed):
    bad = []
    by = {key(r): r for r in recs}
    members_of, readmitted, requested = {}, [], {}   # readmitted: (epoch, node, inc, record key of the commit)
    for r in recs:
        if r['event'] == 'ConfigCommitted' and (r.get('decided') or r['epoch'] == 0):
            members_of.setdefault(r['epoch'], set(r.get('members', [])))
            if r.get('decided'):
                readmitted += [(r['epoch'], n, i, key(r)) for n, i in r.get('readmits', [])]
        if r['event'] in ('ReconfigRequest', 'ReconfigSend'):
            requested.setdefault(r.get('request_id'), set(r.get('members', [])))

    def eligible(node, inc, epoch, deciding):
        return inc == 0 or any(n == node and i == inc and ep <= epoch and k != deciding for ep, n, i, k in readmitted)

    def counted(r):
        out = []
        for i in r.get('inputs', []):
            if i['name'] == 'agreed' and 'ref' in i:
                hit = by.get(rkey(i['ref']))
                if hit and hit['event'] == 'Agreed':
                    out.append(hit)
        return out

    def majority(ags, members, epoch, deciding):
        got = {a['node'] for a in ags
               if a['node'] in members and eligible(a['node'], a.get('node_incarnation', 0), epoch, deciding)}
        return len(got) * 2 > len(members), got

    decided_epochs = defaultdict(list)
    for i, r in enumerate(recs):
        if not is_decision(r):
            continue
        tag = f"{path}: {r['proc']}#{r.get('inc', 0)}.{r['seq']} {r['event']}"
        if 'inputs' not in r:
            bad.append(f"{tag}: no inputs"); continue
        for name in sorted({x['name'] for x in r['inputs']} - allowed):
            bad.append(f"{tag}: input name {name} outside the fixed list")
        m, e = inmap(r), r['event']
        if e in STORAGE:
            tok, led = m.get('token'), m.get('ledger')
            if tok is None or led is None:
                bad.append(f"{tag}: storage inputs lack token or ledger"); continue
            if tok != r.get('token') or led != r.get('highest_before'):
                bad.append(f"{tag}: record disagrees with its inputs")
            if (e in ('WriteAccept', 'ReadAccept')) != (tok >= led):
                bad.append(f"{tag}: outcome contradicts token {tok} vs ledger {led}")
            if e == 'ReadAccept' and r.get('value') != m.get('stored_value'):
                bad.append(f"{tag}: served value is not stored_value")
        elif e == 'Grant':
            mem, ep = m.get('members'), m.get('config_epoch')
            if mem is None or ep is None or ep != r.get('config_epoch'):
                bad.append(f"{tag}: grant inputs lack members/config_epoch or disagree with the record"); continue
            if set(mem) != members_of.get(ep):
                bad.append(f"{tag}: members {sorted(mem)} are not the committed configuration of epoch {ep} (C3.7)")
                mem = sorted(members_of.get(ep, set()))
            ok, got = majority(counted(r), set(mem), ep, key(r))
            if not ok:
                bad.append(f"{tag}: counted eligible nodes {sorted(got)} are not a majority of {sorted(mem)} (C3.7)")
        elif e == 'ConfigCommitted':
            ep = r['epoch']
            decided_epochs[ep].append(i)
            old = members_of.get(ep - 1)
            if old is None:
                bad.append(f"{tag}: no committed configuration of epoch {ep - 1} in the trace (C3.1)"); continue
            ags = counted(r)
            ok_old, _ = majority(ags, old, ep - 1, key(r))
            ok_new, _ = majority(ags, set(r.get('members', [])), ep, key(r))
            if not (ok_old and ok_new):
                bad.append(f"{tag}: not counted by majorities of epoch {ep - 1} and epoch {ep} (C3.8)")
            if r.get('request_id') not in requested:
                bad.append(f"{tag}: no request record for {r.get('request_id')}")
            elif set(r.get('members', [])) != requested[r.get('request_id')]:
                bad.append(f"{tag}: members differ from request {r.get('request_id')}'s (C3.8)")
            for n, inc in r.get('readmits', []):
                if not any(a['node'] == n and a.get('node_incarnation', 0) == inc for a in ags):
                    bad.append(f"{tag}: readmits {n}#{inc} without an Agreed from it for this proposal")
            want = sorted({(a['node'], a.get('node_incarnation', 0)) for a in ags
                           if a.get('node_incarnation', 0) > 0 and a['node'] in r.get('members', [])})
            have = sorted({tuple(x) for x in r.get('readmits', [])})
            if want != have and set(have) <= set(want):
                bad.append(f"{tag}: readmits is not exactly {[list(x) for x in want]}")
    for ep, idx in decided_epochs.items():
        if len(idx) > 1:
            bad.append(f"{path}: epoch {ep} decided {len(idx)} times (C3.1)")
    # Part 2: C1.1 without a global order
    grants = [r for r in recs if r['event'] == 'Grant']
    seen = defaultdict(int)
    for g in grants:
        seen[g.get('token')] += 1
    for tok, n in seen.items():
        if n > 1:
            bad.append(f"{path}: token {tok} granted {n} times (C1.1)")
    for g in grants:
        for h in grants:
            if g.get('config_epoch', 0) < h.get('config_epoch', 0) and not h.get('token', 0) > g.get('token', 0):
                bad.append(f"{path}: grant under epoch {h.get('config_epoch')} with token {h.get('token')} "
                           f"not above epoch {g.get('config_epoch')}'s token {g.get('token')} (C1.1)")
    deciders = defaultdict(set)
    for g in grants:
        deciders[g.get('grantor_term')].add((g['proc'], g.get('inc', 0)))
    for term, ds in deciders.items():
        if len(ds) > 1:
            bad.append(f"{path}: grantor_term {term} decided by {len(ds)} node incarnations")
    counted_props = set()
    for g in grants:
        for a in counted(g):
            counted_props.add((a['node'], a.get('node_incarnation', 0), prop_key(a.get('proposal', {}))))
    agrees = defaultdict(list)
    for r in recs:
        if r['event'] == 'Agree' and 'token' in r.get('proposal', {}) and \
                (r['node'], r.get('incarnation', 0), prop_key(r['proposal'])) in counted_props:
            agrees[r['node']].append(r)
    for node, rs in agrees.items():
        top = None
        for r in sorted(rs, key=lambda x: (x.get('inc', 0), x['seq'])):
            t = r['proposal']['token']
            if top is not None and t <= top:
                bad.append(f"{path}: {node}#{r.get('inc', 0)} agreed to token {t} after token {top} (C1.1)")
            top = t if top is None else max(top, t)
    return bad


def main(argv):
    allowed = set(FIXED)
    if argv[:1] == ['--extra-inputs']:
        allowed |= set(argv[1].split(',')); argv = argv[2:]
    bad, groups = [], defaultdict(lambda: defaultdict(list))
    for p in argv:
        recs = load(p)
        bad += evidence(p, recs, allowed)
        idx = {key(r): r for r in recs}
        for r in recs:
            if is_decision(r) and 'inputs' in r:
                kind, out = outcome(r)
                groups[(kind, canon(r, idx))][out].append(f"{p}:{r['proc']}#{r.get('inc', 0)}.{r['seq']}")
    conflicts = [(k, v) for k, v in groups.items() if len(v) > 1]
    for line in bad:
        print('INVALID', line)
    for (kind, _), outs in conflicts:
        print(f"UNEXPLAINED inputs {kind}: equal inputs, {len(outs)} outcomes: " +
              '; '.join(f"{o} at {w[0]}" for o, w in outs.items()))
    print(f"decision-replay: {len(argv)} traces, {len(bad)} invalid, {len(conflicts)} UNEXPLAINED inputs")
    return 1 if bad or conflicts else 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))

// derives: C1.1, C1.2, C1.3, C1.4, F1.1, F1.2, F2.1, F2.2, F1.3, C2.1, C2.2
package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"sort"
)

// Verdict distinguishes observed clause failure from missing evidence.
// derives: C1.1, C1.2, C1.3, C1.4, C2.1, C2.2
type Verdict struct {
	Clause string
	Reason string
}

// traceGraph is rebuilt from the JSONL, never from implementation state.
// derives: C1.1, C1.2, C1.3, C1.4, F1.1, F1.2, F2.1, F2.2, F1.3, C2.1, C2.2
type traceGraph struct {
	events  map[Ref]Event
	local   map[string][]Event
	ordered []Event
}

// readTrace validates local sequence continuity and reconstructs causal order.
// derives: C1.1, C1.2, C1.3, C1.4, F1.1, F1.2, F2.1, F2.2, F1.3, C2.1, C2.2
func readTrace(path string) (*traceGraph, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	g := &traceGraph{events: map[Ref]Event{}, local: map[string][]Event{}}
	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 4096), 1<<20)
	run := ""
	for scanner.Scan() {
		var v Event
		decoderErr := json.Unmarshal(scanner.Bytes(), &v)
		if decoderErr != nil {
			return nil, decoderErr
		}
		if v.Proc == "" || v.Seq == 0 || v.Side != "impl" || v.Run == "" || !observable(v.Event) && v.Event != "Fault" {
			return nil, fmt.Errorf("malformed observable record")
		}
		if run == "" {
			run = v.Run
		}
		if v.Run != run {
			return nil, fmt.Errorf("mixed runs")
		}
		r := Ref{v.Proc, v.Seq}
		if _, ok := g.events[r]; ok {
			return nil, fmt.Errorf("duplicate event reference %v", r)
		}
		g.events[r] = v
		g.local[v.Proc] = append(g.local[v.Proc], v)
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	if len(g.events) == 0 {
		return nil, fmt.Errorf("empty trace")
	}
	for proc, events := range g.local {
		sort.Slice(events, func(i, j int) bool { return events[i].Seq < events[j].Seq })
		for i, e := range events {
			if e.Seq != uint64(i+1) {
				return nil, fmt.Errorf("missing local sequence on %s", proc)
			}
		}
		g.local[proc] = events
	}
	// Topological sorting uses references and process order, never input line order.
	degree := map[Ref]int{}
	children := map[Ref][]Ref{}
	for r, v := range g.events {
		edges := map[Ref]bool{}
		if r.Seq > 1 {
			edges[Ref{r.Proc, r.Seq - 1}] = true
		}
		for _, cause := range v.Causes {
			edges[cause] = true
		}
		for cause := range edges {
			if _, ok := g.events[cause]; !ok {
				return nil, fmt.Errorf("missing cause %v", cause)
			}
			degree[r]++
			children[cause] = append(children[cause], r)
		}
	}
	var ready []Ref
	for r := range g.events {
		if degree[r] == 0 {
			ready = append(ready, r)
		}
	}
	less := func(i, j int) bool {
		if ready[i].Proc == ready[j].Proc {
			return ready[i].Seq < ready[j].Seq
		}
		return ready[i].Proc < ready[j].Proc
	}
	for len(ready) > 0 {
		sort.Slice(ready, less)
		r := ready[0]
		ready = ready[1:]
		g.ordered = append(g.ordered, g.events[r])
		for _, next := range children[r] {
			degree[next]--
			if degree[next] == 0 {
				ready = append(ready, next)
			}
		}
	}
	if len(g.ordered) != len(g.events) {
		return nil, fmt.Errorf("causal cycle")
	}
	return g, nil
}

// precedes traverses explicit causes plus implicit per-process program order.
// derives: C1.1, C1.2, C1.3, C1.4, F1.1, F1.2, F2.1, F2.2, F1.3, C2.1, C2.2
func (g *traceGraph) precedes(a, b Ref) bool {
	if a == b {
		return false
	}
	stack := []Ref{b}
	seen := map[Ref]bool{}
	for len(stack) > 0 {
		r := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if seen[r] {
			continue
		}
		seen[r] = true
		v, ok := g.events[r]
		if !ok {
			continue
		}
		edges := append([]Ref{}, v.Causes...)
		if r.Seq > 1 {
			edges = append(edges, Ref{r.Proc, r.Seq - 1})
		}
		for _, p := range edges {
			if p == a {
				return true
			}
			stack = append(stack, p)
		}
	}
	return false
}

// directEvent finds an explicit causal parent of a particular event type.
// derives: C1.1, C1.2, C1.3, C2.1, C2.2
func (g *traceGraph) directEvent(e Event, names ...string) (Event, bool) {
	for _, r := range e.Causes {
		v := g.events[r]
		for _, name := range names {
			if v.Event == name {
				return v, true
			}
		}
	}
	return Event{}, false
}

// checkC11 compares all ordered grants and demands a total observable grant order.
// derives: C1.1, F1.1, F1.2, F2.1, F2.2, F1.3, C2.1, C2.2
func (g *traceGraph) checkC11() Verdict {
	var grants []Event
	for _, v := range g.ordered {
		if v.Event == "Grant" {
			if v.Key != "k" || v.Token == 0 || v.Term == 0 || v.Lifetime <= 0 {
				return Verdict{Reason: "malformed grant"}
			}
			r, ok := g.directEvent(v, "Request")
			if !ok || r.Client != v.Client || r.Key != v.Key {
				return Verdict{Reason: "grant lacks matching Request"}
			}
			grants = append(grants, v)
		}
	}
	for i, a := range grants {
		for _, b := range grants[i+1:] {
			ar, br := Ref{a.Proc, a.Seq}, Ref{b.Proc, b.Seq}
			if !g.precedes(ar, br) {
				return Verdict{Reason: "grants lack total causal order"}
			}
			if b.Token <= a.Token {
				return Verdict{Clause: "C1.1", Reason: fmt.Sprintf("grant %v token %d follows token %d", br, b.Token, a.Token)}
			}
		}
	}
	return Verdict{}
}

// checkProvenance checks the authority path for EVERY acceptance and rejection.
// derives: C1.1, C1.2, C1.3, F1.1, F1.2, F2.1, F2.2, F1.3, C2.1, C2.2
func (g *traceGraph) checkProvenance() Verdict {
	for _, e := range g.ordered {
		if e.Event != "WriteAccept" && e.Event != "WriteReject" && e.Event != "ReadAccept" && e.Event != "ReadReject" {
			continue
		}
		attemptName := "WriteAttempt"
		if e.Event == "ReadAccept" || e.Event == "ReadReject" {
			attemptName = "ReadAttempt"
		}
		a, ok := g.directEvent(e, attemptName)
		if !ok || a.Key != e.Key || a.Token != e.Token || a.Term != e.Term || e.HighestBefore == nil {
			return Verdict{Reason: "storage decision lacks matching attempt/ledger"}
		}
		grant, ok := g.directEvent(a, "Grant")
		if !ok || grant.Client != a.Client || grant.Token != a.Token || grant.Term != a.Term || grant.Key != a.Key {
			return Verdict{Reason: "attempt lacks matching grant and grantor term"}
		}
	}
	return Verdict{}
}

// checkC12 reconstructs the durable maximum using storage's own sequence only.
// derives: C1.2, F1.1, F1.2, F2.1, F2.2, F1.3, C2.1, C2.2
func (g *traceGraph) checkC12(storage string) Verdict {
	var highest uint64
	for _, e := range g.local[storage] {
		if e.Event != "WriteAccept" && e.Event != "WriteReject" {
			continue
		}
		if e.HighestBefore == nil {
			return Verdict{Reason: "storage decision missing highest_before"}
		}
		if *e.HighestBefore != highest {
			return Verdict{Clause: "C1.2", Reason: fmt.Sprintf("storage seq %d ledger %d, reconstructed %d", e.Seq, *e.HighestBefore, highest)}
		}
		if e.Event == "WriteAccept" {
			if e.Token < highest {
				return Verdict{Clause: "C1.2", Reason: fmt.Sprintf("storage accepted stale token %d below %d", e.Token, highest)}
			}
			highest = e.Token
		}
	}
	return Verdict{}
}

// checkC13 correlates each success to THIS attempt's acceptance, including late acks.
// derives: C1.3, F1.1, F1.2, F2.1, F2.2, F1.3, C2.1, C2.2
func (g *traceGraph) checkC13() Verdict {
	unknown := Verdict{}
acks:
	for _, ack := range g.ordered {
		if ack.Event != "WriteAck" {
			continue
		}
		if ack.Outcome != "accepted" && ack.Outcome != "rejected" {
			return Verdict{Reason: "unknown ack outcome"}
		}
		if ack.Outcome != "accepted" {
			continue
		}
		decision, ok := g.directEvent(ack, "WriteAccept")
		if !ok {
			// Missing causal evidence alone cannot establish a contract violation.
			// Recover the precise attempt from either the ack or its rejection.
			attempt, found := g.directEvent(ack, "WriteAttempt")
			if !found {
				if rejection, rejected := g.directEvent(ack, "WriteReject"); rejected {
					attempt, found = g.directEvent(rejection, "WriteAttempt")
				}
			}
			if !found {
				unknown = Verdict{Reason: "success ack lacks attempt correlation"}
				continue
			}
			for _, candidate := range g.ordered {
				if candidate.Event != "WriteAccept" {
					continue
				}
				parent, exists := g.directEvent(candidate, "WriteAttempt")
				if exists && (Ref{parent.Proc, parent.Seq}) == (Ref{attempt.Proc, attempt.Seq}) {
					unknown = Verdict{Reason: "success ack omits an existing acceptance reference"}
					continue acks
				}
			}
			return Verdict{Clause: "C1.3", Reason: fmt.Sprintf("success ack %s:%d refers to an attempt never accepted", ack.Proc, ack.Seq)}
		}
		if decision.Key != ack.Key || decision.Token != ack.Token {
			return Verdict{Clause: "C1.3", Reason: "success ack mismatches acceptance key/token"}
		}
		attempt, ok := g.directEvent(decision, "WriteAttempt")
		if !ok || attempt.Client != ack.Client || attempt.Proc != ack.Proc || attempt.Key != ack.Key || attempt.Token != ack.Token {
			return Verdict{Clause: "C1.3", Reason: "success ack mismatches the accepted attempt"}
		}
	}
	return unknown
}

// checkC14 independently reconstructs the final environment from Fault records.
// derives: C1.4, F1.1, F1.2, F2.1, F2.2, F1.3, E1, C2.1, C2.2
func (g *traceGraph) checkC14(s Schedule, evidence RunEvidence) Verdict {
	if len(evidence.Witnesses) == 0 {
		return Verdict{}
	}
	up := map[string]bool{}
	paused := map[string]bool{}
	down := map[link]bool{}
	var lastFault Ref
	for _, id := range append(append(append([]string{}, s.Processes.Lease...), s.Processes.Clients...), s.Processes.Storage...) {
		up[id] = true
	}
	for _, e := range g.local["env"] {
		if e.Event != "Fault" {
			continue
		}
		lastFault = Ref{e.Proc, e.Seq}
		if e.Crash != "" {
			up[e.Crash] = false
			paused[e.Crash] = false
		}
		if e.Restart != "" {
			up[e.Restart] = true
		}
		// Independently reconstruct the directed environment from observable faults.
		// derives: C1.4, F1.2, F2.1, F2.2, L2, L3
		if e.Partition != nil {
			for _, a := range e.Partition[0] {
				for _, b := range e.Partition[1] {
					down[link{a, b}] = true
					down[link{b, a}] = true
				}
			}
		}
		for _, pair := range e.Links {
			if len(pair) != 2 || !upName(s, pair[0]) || !upName(s, pair[1]) || pair[0] == pair[1] {
				return Verdict{Reason: "malformed directed Fault links"}
			}
			down[link{pair[0], pair[1]}] = true
		}
		if e.Heal {
			down = map[link]bool{}
		}
		if e.Pause != "" {
			paused[e.Pause] = true
		}
		if e.Resume != "" {
			paused[e.Resume] = false
		}
	}
	connected := func(a, b string) bool { return up[a] && up[b] && !down[link{a, b}] && !down[link{b, a}] }
	for _, w := range evidence.Witnesses {
		request, ok := g.events[w.Request]
		if !ok || request.Event != "Request" || w.StableFault != lastFault || w.BudgetMillis < 3000 {
			return Verdict{Reason: "invalid progress horizon certificate"}
		}
		client, storage := request.Client, s.Processes.Storage[0]
		if !up[client] || paused[client] || !up[storage] || !connected(client, storage) {
			return Verdict{Reason: "progress certificate has unavailable requester/storage"}
		}
		clique := false
		for i, a := range s.Processes.Lease {
			for _, b := range s.Processes.Lease[i+1:] {
				if connected(a, b) && connected(a, client) && connected(b, client) && connected(a, storage) && connected(b, storage) {
					clique = true
				}
			}
		}
		if !clique {
			return Verdict{Reason: "progress certificate lacks connected majority"}
		}
		if v := g.checkGrantDeliveries(s, evidence); v.Reason != "" {
			return v
		}
		granted := g.requestObtained(w.Request, evidence)
		if !granted {
			return Verdict{Clause: "C1.4", Reason: fmt.Sprintf("eligible request %v unfulfilled through finite horizon", w.Request)}
		}
	}
	return Verdict{}
}

// checkTrace reports clause failures before operational incompleteness.
// derives: C1.1, C1.2, C1.3, C1.4, F1.1, F1.2, F2.1, F2.2, F1.3, E1, E2, C2.1, C2.2
func checkTrace(path string, s Schedule, evidence RunEvidence) Verdict {
