// derives: C1.4, C3.4, C3.7, C3.8, F3.1, F3.3
func cliquePremise(old,new []string,required []string,eligible func(string)bool,connected func(string,string)bool) bool {
 union:=append([]string{},old...);for _,n:=range new{if !contains(union,n){union=append(union,n)}}
 for mask:=1;mask<(1<<len(union));mask++{nodes:=append([]string{},required...);a,b:=0,0
  for i,n:=range union{if mask&(1<<i)!=0&&eligible(n){nodes=append(nodes,n);if contains(old,n){a++};if contains(new,n){b++}}}
  if a*2<=len(old)||b*2<=len(new){continue};ok:=true;for _,x:=range nodes{for _,y:=range nodes{if !connected(x,y){ok=false}}};if ok{return true}
 };return false
}
